const y = vertex.y;
const points = [
    { x: outer.x, y: y, z: outer.z },
    { x: q1Outer.x, y: y, z: q1Outer.z },
    { x: q1Inner.x, y: y, z: q1Inner.z },
    { x: innerCorner.x, y: y, z: innerCorner.z },
    { x: q2Inner.x, y: y, z: q2Inner.z },
    { x: q2Outer.x, y: y, z: q2Outer.z },
];

import { MaStlWallEditFinalize, MaStlWallStretchMath } from './ma-stl-wall-edit-finalize.js';
import {
    maAtk60BuildLFootprintMm,
    maAtk60BuildTFootprintMm,
    maAtk60ClassifyFootprintKind,
} from './ma-stl-atk60-formwork.js';

