    const neg = strip.faceNeg;
    const trimP1 =
        axisEndpointTrimMap && axis.id != null ? axisEndpointTrimMap.get(axis.id + '|p1') || 0 : 0;
    const trimP2 =
        axisEndpointTrimMap && axis.id != null ? axisEndpointTrimMap.get(axis.id + '|p2') || 0 : 0;

    let posStart;
