    const innerSpan = maAtk60SelectPanelMm(2 * MA_ATK60_CORNER_PANEL_MM + Math.max(0, eBranchMm));
    const branchPanel = maAtk60SelectPanelMm(Math.max(0, eBranchMm));

    const u = { x: uUnit.x, z: uUnit.z };
    const v = { x: vUnit.x, z: vUnit.z };
    const nProbe = maAtk60NormalXz(u, 1);
    const nearSign = nProbe.x * v.x + nProbe.z * v.z >= 0 ? 1 : -1;
    const nu = maAtk60NormalXz(u, nearSign);

