        return {
            x: vertex.x + u.x * au + v.x * av + nu.x * an,
            y: y,
            z: vertex.z + u.z * au + v.z * av + nu.z * an,
        };
    };

    const points = [
        p(-hu, 0, anNear),
        p(-innerHalf, 0, anNear),
        p(-innerHalf, stem, anStem),
        p(innerHalf, stem, anStem),
        p(innerHalf, 0, anNear),
        p(hu, 0, anNear),
        p(hu, 0, anFar),
        p(-hu, 0, anFar),
    ];

    return {
        points: points,
        meta: {
            kind: 'cornerT',
            system: 'Atk-60',
            eThroughMm: eThroughMm,
            eBranchMm: eBranchMm,
