function maStlAtk60DisposeFootprintGuideRoot(root) {
    if (!root) return;
    root.traverse(function (obj) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
            if (Array.isArray(obj.material)) {
                obj.material.forEach(function (m) {
                    if (m) m.dispose();
                });
            } else {
                obj.material.dispose();
            }
        }
    });
}

function maStlAtk60ClearDimPointGuides() {
    while (maStlAtk60DimPointGuideGroup.children.length > 0) {
        const ch = maStlAtk60DimPointGuideGroup.children[0];
        maStlAtk60DimPointGuideGroup.remove(ch);
        maStlAtk60DisposeFootprintGuideRoot(ch);
    }
}

function maStlAtk60AddFootprintPointGuide(footprint, parentGroup, showPointMarkers) {
    if (!footprint || !footprint.points || footprint.points.length < 3 || !parentGroup) return false;
    const pts = footprint.points;
    const labels =
        (footprint.meta && footprint.meta.pointLabels) ||
        pts.map(function (_p, i) {
            return 'L-' + (i + 1);
        });
    const floorY = MA_STL_DESING2_WORKSPACE_FLOOR_Y_MM + 12;
    const root = new THREE.Group();
    root.userData.maStlWall3dGenerated = true;
    root.userData.maStlAtk60FootprintGuide = true;
    root.renderOrder = 200;

    const linePos = [];
    for (let i = 0; i < pts.length; i++) {
        linePos.push(pts[i].x, floorY, pts[i].z);
    }
    linePos.push(pts[0].x, floorY, pts[0].z);
    const lineGeo = new THREE.BufferGeometry();
    lineGeo.setAttribute(
        'position',
        new THREE.Float32BufferAttribute(new Float32Array(linePos), 3)
    );
    const lineMat = new THREE.LineBasicMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0.95,
        depthTest: false,
        depthWrite: false,
    });
    const loop = new THREE.LineLoop(lineGeo, lineMat);
    loop.renderOrder = 200;
    root.add(loop);

    const pointColors = [
        0xff5252,
        0xff9800,
        0xffeb3b,
        0x8bc34a,
        0x00bcd4,
        0x2196f3,
        0x9c27b0,
        0xe91e63,
    ];
    const labelScale = 170;
    const dotRadius = 120;
    if (showPointMarkers) {
        for (let li = 0; li < pts.length; li++) {
            const col = pointColors[li % pointColors.length];
            const colHex = '#' + col.toString(16).padStart(6, '0');
            const sp = maStlMakeTextSprite(labels[li] || 'L-' + (li + 1), labelScale, {
                thinFillOnly: true,
                fillColor: colHex,
                fontPx: 16,
                fontWeight: 600,
                canvasPad: 2,
                thinPillFill: 'rgba(0,0,0,0.6)',
                thinPillRadiusPx: 6,
            });
            if (sp) {
                sp.position.set(pts[li].x, floorY + labelScale * 0.45, pts[li].z);
                sp.renderOrder = 201;
                root.add(sp);
            }
            const dot = new THREE.Mesh(
                new THREE.SphereGeometry(dotRadius, 14, 12),
                new THREE.MeshBasicMaterial({
                    color: col,
                    depthTest: false,
                    depthWrite: false,
                })
            );
            dot.position.set(pts[li].x, floorY, pts[li].z);
            dot.renderOrder = 199;
            root.add(dot);
            const ring = new THREE.Mesh(
                new THREE.RingGeometry(dotRadius * 1.15, dotRadius * 1.45, 24),
