            ring.rotation.x = -Math.PI / 2;
            ring.position.set(pts[li].x, floorY + 1, pts[li].z);
            ring.renderOrder = 198;
            root.add(ring);
        }
    }

    maStlDisableRaycastOnOverlay(root);
    parentGroup.add(root);
    return true;
