function maStlAtk60AddTFootprintPointGuide(footprint, useWall3dGroup) {
    const parent =
        useWall3dGroup && maStlWall3dMeshesGroup
            ? maStlWall3dMeshesGroup
            : maStlWall2dModelMeshesGroup;
    if (!parent) return false;
    if (!useWall3dGroup && maStlWall2dModelMeshesGroup) {
        maStlWall2dModelMeshesGroup.visible = true;
    }
    return maStlAtk60AddFootprintPointGuide(
        footprint,
        parent,
        MA_STL_ATK60_T_SHOW_POINT_MARKERS
    );
}

function maStlAtk60RefreshDimPointGuides(footprints) {
    maStlAtk60ClearDimPointGuides();
    if (!footprints || footprints.length === 0) return 0;
    let count = 0;
    for (let i = 0; i < footprints.length; i++) {
        if (maStlAtk60AddFootprintPointGuide(footprints[i], maStlAtk60DimPointGuideGroup, true)) {
            count++;
        }
    }
    return count;
}

